using Microsoft.UI.Xaml;using System;using System.Threading.Tasks;using VicarShotgunKeyboard.Services;
namespace VicarShotgunKeyboard;
public partial class App:Application
{
 public static AppSettingsStore Settings{get;private set;}=null!;public static AudioEngine Audio{get;private set;}=null!;public static SoundManager Sounds{get;private set;}=null!;public static KeyboardHookService Keyboard{get;private set;}=null!;public static MainWindow MainWindow{get;private set;}=null!;public static AppLogger Logger{get;private set;}=null!;
 protected override async void OnLaunched(LaunchActivatedEventArgs args){Logger=new AppLogger();try{Settings=new AppSettingsStore(Logger);await Settings.LoadAsync();Sounds=new SoundManager(Logger);Sounds.LoadBuiltInSounds();Audio=new AudioEngine(Logger,Sounds);await Audio.InitializeAsync();Keyboard=new KeyboardHookService(Logger);MainWindow=new MainWindow();MainWindow.InitializeServices();MainWindow.Activate();Keyboard.ApplyFilters(Settings.Current.TriggerFilters);Keyboard.IgnoreRepeat=Settings.Current.IgnoreKeyRepeat;Keyboard.PlayOnRelease=Settings.Current.PlayOnKeyRelease;Keyboard.Start();if(!Settings.Current.FirstLaunchCompleted)MainWindow.ShowWelcome();Logger.Info("Application started");}catch(Exception e){Logger.Error("Startup failure",e);}}
 public static void ApplySettings(){Audio.SetVolume(Settings.Current.Volume);Audio.SetMuted(Settings.Current.Muted);Audio.SetRandomize(Settings.Current.RandomizeSounds);Audio.SetMaxVoices(Settings.Current.MaxSimultaneousSounds);Audio.SetOverlap(Settings.Current.AllowOverlappingSounds);Audio.SetSelectedSound(Settings.Current.SelectedSound);Keyboard.ApplyFilters(Settings.Current.TriggerFilters);Keyboard.IgnoreRepeat=Settings.Current.IgnoreKeyRepeat;Keyboard.PlayOnRelease=Settings.Current.PlayOnKeyRelease;}
 public static Task SaveSettingsAsync()=>Settings.SaveAsync();public static void Shutdown(){try{Keyboard?.Stop();}catch{}try{Audio?.Dispose();}catch{}try{Logger?.Info("Application shutdown");Logger?.Dispose();}catch{}}
}